package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry.LF_DIR;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TarArchiveEntry_isDirectory_TriageGen1Test {

    /**
     * Helper to set the private 'file' field via reflection for testing purposes.
     */
    private void setFileField(TarArchiveEntry entry, File file) throws Exception {
        Field fileField = TarArchiveEntry.class.getDeclaredField("file");
        fileField.setAccessible(true);
        fileField.set(entry, file);
    }

    /**
     * Helper to set the private 'linkFlag' field via reflection.
     */
    private void setLinkFlagField(TarArchiveEntry entry, byte linkFlag) throws Exception {
        Field linkFlagField = TarArchiveEntry.class.getDeclaredField("linkFlag");
        linkFlagField.setAccessible(true);
        linkFlagField.set(entry, linkFlag);
    }

    @Test
    public void testIsDirectory_WithFile_ReturnsFileIsDirectory() throws Exception {
        // Case: file != null and file.isDirectory() is true
        File dirFile = new File("/"); 
        // Note: In most environments, "/" is a directory. 
        // To be safe for a unit test, we rely on the actual file system or mock if possible.
        // Since TarArchiveEntry is a concrete class and we want to test its logic:
        TarArchiveEntry entry = new TarArchiveEntry("some/path");
        setFileField(entry, dirFile);

        assertTrue(entry.isDirectory());
    }

    @Test
    public void testIsDirectory_WithFile_ReturnsFileIsNotDirectory() throws Exception {
        // Case: file != null and file.isDirectory() is false
        // We use a file that is guaranteed to exist but not be a directory if possible, 
        // or just rely on the logic path.
        File regularFile = new File("test.txt");
        regularFile.createNewFile();
        try {
            TarArchiveEntry entry = new TarArchiveEntry("some/path");
            setFileField(entry, regularFile);
            assertFalse(entry.isDirectory());
        } finally {
            regularFile.delete();
        }
    }

    @Test
    public void testIsDirectory_WithLinkFlagDir_ReturnsTrue() throws Exception {
        // Case: file == null AND linkFlag == LF_DIR
        TarArchiveEntry entry = new TarArchiveEntry("testname");
        setLinkFlagField(entry, LF_DIR);

        assertTrue(entry.isDirectory());
    }

    @Test
    public void testIsDirectory_WithNameEndingWithSlash_ReturnsTrue() throws Exception {
        // Case: file == null AND linkFlag != LF_DIR AND name ends with "/"
        TarArchiveEntry entry = new TarArchiveEntry("testname/");
        setLinkFlagField(entry, (byte) 0); // Not LF_DIR

        assertTrue(entry.isDirectory());
    }

    @Test
    public void testIsDirectory_AllFalse_ReturnsFalse() throws Exception {
        // Case: file == null AND linkFlag != LF_DIR AND name does not end with "/"
        TarArchiveEntry entry = new TarArchiveEntry("testname");
        setLinkFlagField(entry, (byte) 0);

        assertFalse(entry.isDirectory());
    }

    @Test
    public void testIsDirectory_WithLinkFlagDirAndFileNotNull_PrioritizesFile() throws Exception {
        // Case: file != null (even if file is not a dir), linkFlag is LF_DIR
        // The code checks 'if (file != null)' first.
        File regularFile = new File("test_priority.txt");
        regularFile.createNewFile();
        try {
            TarArchiveEntry entry = new TarArchiveEntry("testname");
            setFileField(entry, regularFile);
            setLinkFlagField(entry, LF_DIR);

            // Should return false because file.isDirectory() is false and it hits the first block
            assertFalse(entry.isDirectory());
        } finally {
            regularFile.delete();
        }
    }
}
